<?php
namespace App\Models;use Illuminate\Foundation\Auth\User as Authenticatable;use Illuminate\Notifications\Notifiable;
class User extends Authenticatable {use Notifiable;protected $guarded=[];protected $hidden=['password','remember_token'];protected $casts=['email_verified_at'=>'datetime','registration_confirmed_at'=>'datetime','is_active'=>'boolean','is_legal_entity'=>'boolean'];public function enrollments(){return $this->hasMany(Enrollment::class);}public function permissions(){return $this->belongsToMany(AdminPermission::class,'admin_permission_user','user_id','permission_id');}public function mailingAddress(){return $this->hasOne(MailingAddress::class);}public function parentOrganization(){return $this->belongsTo(self::class,'parent_user_id');}public function isAdmin():bool{return $this->role==='admin';}public function isCurator():bool{return in_array($this->role,['curator','admin'],true);}public function hasAdminPermission(string $key):bool{return $this->isAdmin()&&(!$this->permissions()->exists()||$this->permissions()->where('key',$key)->exists());}}
